WITH base AS (SELECT id, email, dept_id, job_title, salary, hire_date, level, UPPER(level) level_upper, COALESCE(level, 'UNKNOWN') level_filled FROM employees WHERE hire_date > DATE '2023-06-30' AND dept_id IN (16, 20, 21, 33)) SELECT id, email, dept_id, job_title, salary, hire_date, level, level_upper, level_filled, MIN(salary) OVER (PARTITION BY dept_id) dept_id_min_salary, LAST_VALUE(job_title, TRUE) OVER (PARTITION BY job_title ORDER BY salary, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) last_known_job_title, ROUND(salary / SUM(salary) OVER (PARTITION BY level), 4) salary_share FROM base
